"""stages.profile: generated by the graph.py split (P1)."""

from __future__ import annotations

import json
import re
from pathlib import Path
from typing import Any

from .. import ir, profile_cache
from ..benchmark import embench, embench_instrument, generic
from ..flow import outcome
from ..runtime import commands as commands_mod, effects, stage_services, tools
from ..runtime.policy import PolicyError
from ..state import CfuDesignState


def _profile_verdict(state: CfuDesignState, *, ok: bool, skipped: bool, **evidence) -> dict:
    failed = not ok and not skipped
    update = outcome.stage_result(state, rung="profile", ok=ok, skipped=skipped,
        next="review_and_route" if failed else "extract_hotspot",
        terminal_reason="profile_precondition" if failed else "",
        failure_kind="precondition_failure" if failed else "", **evidence)
    if failed:
        update.update(stopped_at="profile", stage_jobs="review")
    return update


def profile_embench(state: CfuDesignState) -> CfuDesignState:
    """Build and simulate the reference/profile(/cfu) configurations.

    reference : plain build, must pass Embench verify, gives baseline cycles
    profile   : reference + observation points, gives the per-function table
    cfu       : only when a design patch was applied; must still pass
    """
    spec = state.get("workload_spec", {})
    project = state.get("benchmark_project", {})
    run_root = state.get("run_root", "")
    name = str(project.get("benchmark", "") or spec.get("benchmark_name", ""))
    reason = stage_services._profile_reason(state)
    execute = bool(state.get("run_commands", False)) and not state.get("dry_run", False) and not state.get("skip_sim", False)

    # The cfu configuration is built and simulated by the validation ladder
    # (build_sw/simulate), never during profiling.
    configs = ["reference", "profile"]

    results: list[dict] = []
    profiles: dict[str, dict] = {}
    errors: list[str] = []
    observation: dict = {}

    if not execute:
        planned = [
            stage_services._skipped_result(embench.build_command(run_root, name, config), state, reason)
            for config in configs
        ]
        profile = generic.profile_result_from_commands(planned, dry_run=True, planned_reason=reason)
        _write_embench_profile_artifact(state, name, {}, planned, reason)
        return {
            "profile_result": profile,
            "embench_profiles": {},
            "observation_report": {},
            "stage_jobs": "hotspot",
            **_profile_verdict(state, ok=False, skipped=True, reason=reason,
                                   history=f"Skipped embench profiling ({reason})."),
        }

    toolbox = stage_services._toolbox_for_stage(state, "profile")
    integrity_problems = stage_services.benchmark_integrity_problems(toolbox)
    if integrity_problems:
        message = "benchmark integrity: " + "; ".join(integrity_problems)
        _write_embench_profile_artifact(state, name, {}, [], message,
            benchmark_integrity={"version": 1, "ok": False, "problems": integrity_problems})
        return {
            "profile_result": {"status": "failed", "command_results": [], "regions": [], "summary": message},
            "embench_profiles": {}, "observation_report": {}, "errors": integrity_problems,
            "stage_jobs": "hotspot",
            **_profile_verdict(state, ok=False, skipped=False,
                measurement=dict(project.get("measurement") or {}),
                measurement_protocol=(project.get("measurement") or {}).get("protocol", "legacy"),
                benchmark_integrity={"version": 1, "ok": False, "problems": integrity_problems},
                history="Rejected benchmark preparation before cache lookup or profiling."),
        }

    # The reference/profile configurations are scalar and are simulated on the
    # seeded scaffold (profiling runs before any hardware edit), so the
    # measurement is design-independent and deterministic. Reuse it when every
    # input that shapes the ELF or the SoC matches.
    cache_mode = str(state.get("profile_cache", "on") or "on")
    profile_sources = {
        rel: toolbox.read_text(rel, limit=2_000_000)
        for rel in embench.config_sources(toolbox.workdir, run_root, name, "profile")
    }
    planned_observation = state.get("observation_plan")
    if not planned_observation:
        # Compute the default plan from clean sources, even on a second profile
        # invocation in the same run (whose profile copy may already be edited).
        reference_sources = {
            rel: toolbox.read_text(rel, limit=2_000_000)
            for rel in embench.config_sources(toolbox.workdir, run_root, name, "reference")
        }
        planned_observation = {"points": embench_instrument.default_plan(reference_sources)}
    cache_info = profile_cache.build_key(
        toolbox.workdir,
        run_root=run_root,
        benchmark=name,
        configs=configs,
        build_commands={
            config: embench.build_command(run_root, name, config) for config in configs
        },
        cpu_flags=commands_mod.agent_cfu_gen_flags(state.get("isa_spec", {}) or {}),
        observation_plan=planned_observation,
        measurement_protocol=(project.get("measurement") or {}).get("protocol"),
    )
    cache_key = str(cache_info["key"])
    cache_rel = profile_cache.cache_relpath(cache_key)
    cached: dict | None = None
    if cache_mode == "on":
        try:
            cache_text = toolbox.read_text(cache_rel, limit=5_000_000)
        except PolicyError:
            cache_text = ""
        if cache_text:
            cached = profile_cache.parse(cache_text, cache_key)

    if cached is not None:
        profiles = {
            config: dict(regions)
            for config, regions in (cached.get("profiles") or {}).items()
        }
        observation = dict(cached.get("observation") or {})
        # A reused measurement has no build outputs of its own, so put the
        # cached reference disassembly back: the analysis reads it as the ASM
        # candidate for a measured loop (observed 2026-09-30: `inspect` returned
        # "missing or empty" on every cached run).
        _restore_reference_disassembly(toolbox, run_root, name, cache_key, cache_mode)

    if cached is None:
        if "profile" in configs:
            instrumented, report = embench_instrument.instrument_sources(profile_sources, planned_observation)
            observation = report.to_dict()
            for rel, text in instrumented.items():
                toolbox.write_text(rel, text)

        for config in configs:
            # Through effects.run_command so the build leaves a full log under
            # 05_profile/logs, like every validation and cost command.
            build = effects.run_command(
                state, toolbox,
                embench.build_command(run_root, name, config),
                stage="profile", rung="embench_build", command_id="embench_build",
                timeout=1800, mutate=True, log_stage="profile",
            )
            results.append(build)
            if build.get("returncode") not in (0, None):
                errors.append(f"embench {config} build failed")
                break
            elf = embench.elf_path(run_root, name, config)
            sim_commands = commands_mod.agent_cfu_sim_commands(state, state.get("isa_spec", {}) or {}, elf=elf)
            for sim_command in sim_commands:
                sim = effects.run_command(
                    state, toolbox, sim_command,
                    stage="profile", rung="soc_sim", command_id="soc_sim",
                    timeout=3600, mutate=False, log_stage="profile",
                )
                results.append(sim)
                text = "\n".join([sim.get("stdout_tail", ""), sim.get("stderr_tail", "")])
                profiles[config] = (
                    (sim.get("parsed") or {}).get("embench_profile")
                    or embench.parse_profile(text)
                )
                verify = (sim.get("parsed") or {}).get("verify") or {}
                if verify.get("status") == "fail":
                    errors.append(f"embench {config} baseline verification failed")
                if config == "reference":
                    errors.extend(_baseline_problems(profiles[config], name))
                if sim.get("returncode") not in (0, None):
                    errors.append(
                        f"embench {config} simulation failed (Embench verify did not pass)"
                    )
                    break
                if errors:
                    break
            if errors:
                break
        # Keep the reference disassembly with the measurement it belongs to, so
        # a later run that reuses this entry still has the ASM evidence.
        _store_reference_disassembly(toolbox, run_root, name, cache_key, cache_mode)

    reference = profiles.get("reference", {})
    instrumented = embench_instrumented_profile(profiles)
    applied_ids = set(observation.get("applied", []))
    observed_points = {
        str(point.get("id")): point for point in observation.get("points", [])
        if isinstance(point, dict) and point.get("id") in applied_ids
    }
    loop_profiles = {
        ident: data for ident, data in instrumented.items()
        if ident in observed_points and observed_points[ident].get("kind") == "loop"
        and isinstance(data, dict) and data.get("calls", 0) > 0
    }
    function_profiles = {
        ident: data for ident, data in instrumented.items()
        if ident in observed_points and observed_points[ident].get("kind") == "function"
        and isinstance(data, dict) and data.get("calls", 0) > 0
    }
    hot = (embench.hotspot_from_profile(loop_profiles) or embench.hotspot_from_profile(function_profiles)
           or embench.hotspot_from_profile(instrumented, exclude=(name, "obs_overflow")) or name)
    candidates = [region for region in instrumented if region != name and region != "obs_overflow"]
    expected_loops = [point for point in observation.get("points", [])
                      if isinstance(point, dict) and point.get("kind") == "loop"
                      and point.get("id") in applied_ids]
    errors.extend(problem for problem in _baseline_problems(reference, name) if problem not in errors)
    ok = bool(reference) and bool(instrumented) and not errors
    if expected_loops and not loop_profiles:
        errors.append("no requested loop observation produced cycle/call evidence")
        ok = False

    integrity_problems = stage_services.benchmark_integrity_problems(toolbox)
    errors.extend(problem for problem in integrity_problems if problem not in errors)
    if integrity_problems:
        ok = False
    saved = False
    if ok and cache_mode in ("on", "refresh"):
        try:
            toolbox.write_text(
                cache_rel,
                profile_cache.serialize(
                    cache_key,
                    benchmark=name,
                    configs=configs,
                    profiles=profiles,
                    observation=observation,
                    inputs=cache_info["inputs"],
                ),
            )
            saved = True
        except PolicyError:
            saved = False

    if cached is not None:
        cache_status = "hit"
    elif cache_mode == "off":
        cache_status = "disabled"
    elif cache_mode == "refresh":
        cache_status = "refresh"
    else:
        cache_status = "miss"
    cache_report: dict[str, Any] = {
        "status": cache_status,
        "key": cache_key,
        "saved": saved,
        "benchmark": name,
    }
    if cached is not None:
        cache_report["created_at"] = str(cached.get("created_at", ""))

    profile = {
        "status": "profiled" if ok else "failed",
        "command_results": results,
        "regions": [
            {"name": region, "cycles": data.get("cycles", 0), "source": "embench"}
            for region, data in instrumented.items()
        ],
        "hot_spot": hot,
        "hot_spot_point": observed_points.get(hot, {}),
        "summary": summarize_embench_profiles(profiles, name),
        "configs": sorted(profiles),
        "profile_cache": cache_report,
    }
    _write_embench_profile_artifact(state, name, profiles, results, "", observation, cache_report,
        benchmark_integrity={"version": 1, "ok": not integrity_problems, "problems": integrity_problems},
        ok=ok, errors=errors)
    stage_services._artifacts_for_stage(state, "profile").set_manifest_metadata(
        "profile", "profile_cache", cache_report
    )
    history = (
        f"Reused the cached reference/profile measurement for {name} "
        f"(key {cache_key[:12]}, saved 2 builds + 2 simulations)."
        if cached is not None
        else "Profiled embench " + name + " (" + ", ".join(sorted(profiles)) + ")"
    )
    return {
        "profile_result": profile,
        "embench_profiles": profiles,
        "observation_report": observation,
        "stage_jobs": "hotspot",
        "errors": errors,
        **_profile_verdict(state, ok=ok, skipped=False,
                               configs=sorted(profiles), profile_cache=cache_report,
                               measurement=dict(project.get("measurement") or {}),
                               measurement_protocol=(project.get("measurement") or {}).get("protocol", "legacy"),
                               benchmark_integrity={"version": 1, "ok": not integrity_problems, "problems": integrity_problems},
                               history=history),
    }


def _baseline_problems(reference: dict, name: str) -> list[str]:
    record = reference.get(name) or {}
    cycles = record.get("cycles") if isinstance(record, dict) else None
    problems = []
    if not isinstance(cycles, int) or isinstance(cycles, bool) or cycles <= 0:
        problems.append("reference baseline has no positive benchmark cycle evidence")
    if isinstance(record, dict) and record.get("verify") == 0:
        problems.append("reference baseline verification failed")
    return problems


def embench_instrumented_profile(profiles: dict[str, dict]) -> dict:
    """The config that carries observation points, falling back to reference."""
    return profiles.get("profile", {}) or profiles.get("reference", {})


def _reference_disassembly_rel(run_root: str, name: str) -> str:
    """Where the Makefile leaves the reference build's disassembly."""
    return f"{embench.config_workspace(run_root, name, 'reference')}/{profile_cache.DISASSEMBLY_NAME}"


def _store_reference_disassembly(
    toolbox, run_root: str, name: str, cache_key: str, cache_mode: str,
) -> None:
    """Copy the freshly built reference disassembly into the cache entry."""
    if cache_mode not in ("on", "refresh"):
        return
    try:
        text = toolbox.read_text(_reference_disassembly_rel(run_root, name), limit=10_000_000)
    except PolicyError:
        return
    if not text:
        return
    try:
        toolbox.write_text(profile_cache.artifact_relpath(cache_key, profile_cache.DISASSEMBLY_NAME), text)
    except (PolicyError, OSError):
        # An incomplete cache entry is a missed optimization, never a gate.
        return


def _restore_reference_disassembly(
    toolbox, run_root: str, name: str, cache_key: str, cache_mode: str,
) -> None:
    """Put a cached reference disassembly back into the run workspace.

    The disassembly is a build output: a reused measurement has none, so without
    this an analysis of a cached run cannot read the reference instructions of
    its measured loop.
    """
    if cache_mode not in ("on", "refresh"):
        return
    target = _reference_disassembly_rel(run_root, name)
    if (toolbox.workdir / target).is_file():
        return
    try:
        text = toolbox.read_text(
            profile_cache.artifact_relpath(cache_key, profile_cache.DISASSEMBLY_NAME),
            limit=10_000_000,
        )
    except PolicyError:
        return
    if not text:
        return
    try:
        toolbox.write_text(target, text)
    except (PolicyError, OSError):
        return


def summarize_embench_profiles(profiles: dict[str, dict], name: str) -> str:
    parts: list[str] = []
    for config, data in sorted(profiles.items()):
        cycles = data.get(name, {}).get("cycles", 0)
        parts.append(f"{config}={cycles}")
    return ", ".join(parts) if parts else "no profile lines parsed"


def _write_embench_profile_artifact(
    state: CfuDesignState,
    name: str,
    profiles: dict[str, dict],
    results: list[dict],
    reason: str,
    observation: dict | None = None,
    profile_cache: dict | None = None,
    *, benchmark_integrity: dict | None = None, ok: bool | None = None,
    errors: list[str] | None = None,
) -> None:
    artifacts = stage_services._artifacts_for_stage(state, "profile")
    artifacts.write_yaml(
        "profile",
        "05_profile/embench.yaml",
        {
            "benchmark": name,
            "measurement": dict((state.get("benchmark_project") or {}).get("measurement") or {}),
            "measurement_protocol": ((state.get("benchmark_project") or {}).get("measurement") or {}).get("protocol", "legacy"),
            "benchmark_integrity": benchmark_integrity or {},
            "terminal_reason": "profile_precondition" if ok is False else "",
            "failure_kind": "precondition_failure" if ok is False else "",
            "errors": list(errors or []),
            "reason": reason,
            "profiles": profiles,
            "observation": observation or {},
            "profile_cache": profile_cache or {},
            "commands": [dict(item) for item in results],
        },
        status=("failed" if ok is False or (benchmark_integrity and not benchmark_integrity.get("ok"))
                else "planned" if reason else "produced"),
    )


def instrument_and_profile(state: CfuDesignState) -> CfuDesignState:
    project = state.get("benchmark_project", {})
    commands = generic.profile_commands(project)
    reason = stage_services._profile_reason(state)
    execute = state.get("run_commands", False) and not state.get("dry_run", False) and not state.get("skip_sim", False)
    errors: list[str] = []
    if not execute:
        if not commands:
            commands = [["make", "TARGET=vexii_soc", "MARCH=rv32imc_zicsr_zifencei", "compile"]]
        results = [
            stage_services._skipped_result(command, state, reason)
            for command in commands
        ]
        profile = generic.profile_result_from_commands(results, dry_run=True, planned_reason=reason)
    else:
        toolbox = stage_services._toolbox_for_stage(state, "profile")
        results = []
        for command in commands:
            try:
                command_id = tools.infer_command_id(command, toolbox.policy)
            except PolicyError:
                errors.append(f"profile command is not allowlisted and was skipped: {' '.join(command)}")
                continue
            if not toolbox.command_allowed(command, command_id=command_id):
                errors.append(f"profile command is not allowlisted and was skipped: {' '.join(command)}")
                continue
            result = toolbox.run_command(command, command_id=command_id, timeout=3600, mutate=True, execute=True)
            results.append(result)
            if result.get("returncode") not in (0, None):
                break
        profile = generic.profile_result_from_commands(results, dry_run=False)
    stage_services._write_profile_artifact(state, profile, reason)
    return {
        "profile_result": profile,
        "stage_jobs": "hotspot",
        **_profile_verdict(state, ok=stage_services._profile_ok(profile) and not errors,
                               skipped=not execute, reason=reason,
                               history="Profiled the prepared workload."),
        "errors": errors,
    }


def extract_hotspot(state: CfuDesignState) -> CfuDesignState:
    profile = state.get("profile_result", {})
    spec = dict(state.get("workload_spec", {}))
    project = state.get("benchmark_project", {})
    candidates = project.get("candidate_hotspots", [])
    preferred_kernel = spec.get("kernel_function", "")
    if preferred_kernel == "main" and candidates:
        preferred_kernel = candidates[0]
    hot = (
        profile.get("hot_spot")
        or preferred_kernel
        or (candidates[0] if candidates else "")
        or spec.get("operation", "scalar_kernel")
    )
    point = profile.get("hot_spot_point", {}) or {}
    source = "profile" if profile.get("hot_spot") else "static"
    if profile.get("regions"):
        candidates = [region.get("name", "") for region in profile["regions"]] or candidates
    if point.get("kind") == "loop":
        # Preserve the real source function as the software edit target; a loop
        # observation id is not a function symbol.
        spec["kernel_function"] = point["function"]
        spec["hot_loop"] = {key: point[key] for key in ("id", "file", "function", "line", "ordinal", "loop_kind") if key in point}
    if point.get("kind") == "loop" or not spec.get("hot_spot"):
        spec["hot_spot"] = hot
    spec_text = state.get("spec_text", "")
    if point.get("kind") == "loop" and "hot_spot:" in spec_text:
        spec_text = re.sub(r"(?m)^hot_spot:.*$", f"hot_spot: {hot}", spec_text)
    elif "hot_spot:" not in spec_text:
        spec_text = spec_text.rstrip() + f"\nhot_spot: {hot}\n"
    if point.get("kind") == "loop":
        if "hot_loop:" not in spec_text:
            spec_text = spec_text.rstrip() + "\nhot_loop: " + json.dumps(spec["hot_loop"]) + "\n"
        if "kernel_function:" in spec_text:
            spec_text = re.sub(r"(?m)^kernel_function:.*$", f"kernel_function: {point['function']}", spec_text)
        else:
            spec_text = spec_text.rstrip() + f"\nkernel_function: {point['function']}\n"
    stage_services._write_hotspot_artifact(state, hot, source, candidates)
    return {
        "workload_spec": spec,
        "spec_text": spec_text,
        "hot_spot": hot,
        "stage_jobs": "ir",
        **outcome.stage_result(state, rung="hotspot", ok=bool(hot), source=source,
                               history=f"Selected hot spot `{hot}` for CFU analysis."),
    }


def collect_ir_evidence(state: CfuDesignState) -> CfuDesignState:
    """Optional P0 export; no IR-derived loop ranking or cycle estimates."""
    mode = str(state.get("ir_features", "off") or "off")
    project = state.get("benchmark_project", {}) or {}
    name = str(project.get("benchmark", "") or "")
    result: dict[str, Any] = {"schema_version": "1", "status": "off", "reason": "disabled"}
    files: dict[str, str] = {}
    if mode not in {"off", "auto", "require", "approx"}:
        result = {"schema_version": "1", "status": "failed", "reason": f"invalid IR mode: {mode}"}
    elif mode != "off" and state.get("dry_run", False):
        result = {"schema_version": "1", "status": "unavailable", "reason": "dry-run: IR commands not executed"}
    elif mode != "off" and not state.get("run_commands", False):
        result = {"schema_version": "1", "status": "unavailable", "reason": "execution-disabled: IR commands not executed"}
    elif mode != "off" and project.get("kind") != "embench_benchmark":
        result = {"schema_version": "1", "status": "unavailable", "reason": "P0 supports Embench C sources only"}
    elif mode != "off":
        try:
            result, files = ir.export_embench_ir(
                Path(state.get("workdir", ".")).resolve(),
                str(state.get("run_root", "")), name, mode=mode,
            )
        except (OSError, ValueError, RuntimeError) as exc:
            result = {"schema_version": "1", "status": "failed", "reason": f"IR export: {exc}"}
    result = {**result, "mode": mode}
    if mode == "off":
        return {"stage_jobs": "analysis"}
    # IR is analysis-only, independent of profile and cost caches. Preserve the
    # entire auditable result even when the opt-in toolchain cannot compile.
    try:
        artifacts = stage_services._artifacts_for_stage(state, "analysis")
        recorded: list[str] = []
        feature_files: list[str] = []
        feature_errors: list[str] = []
        hot = state.get("workload_spec", {}).get("hot_loop", {}) or {}
        hot_stem = Path(str(hot.get("file", "") or "")).stem
        hot_function = str(hot.get("function", "") or "")
        hot_line = hot.get("line") if isinstance(hot.get("line"), int) else None
        try:
            from ..ir.features import extract_ir_features, render_features_xml
        except Exception:  # optional module; the IR export stays authoritative
            extract_ir_features = None  # type: ignore[assignment]
        for relative, text in sorted(files.items()):
            ref = artifacts.write_text("analysis", relative, text, kind="llvm_ir")
            recorded.append(ref["path"])
            if extract_ir_features is None:
                continue
            # Best-effort static feature XML (data movement / typed ops /
            # dependencies); it must never break the IR evidence path.
            try:
                stem = Path(relative).stem
                features, _audit = extract_ir_features(
                    text,
                    source_file=f"{stem}.c",
                    function=hot_function if stem == hot_stem else "",
                    hotspot_line=hot_line if stem == hot_stem else None,
                )
                xml_rel = relative[:-3] + ".features.xml"
                xref = artifacts.write_text(
                    "analysis", xml_rel, render_features_xml(features), kind="llvm_features",
                )
                feature_files.append(xref["path"])
            except Exception as exc:
                feature_errors.append(f"{relative}: {type(exc).__name__}: {exc}")
        result["ir_files"] = recorded
        result["feature_files"] = feature_files
        if feature_errors:
            result["feature_extraction"] = {
                "status": "partial" if feature_files else "unavailable",
                "errors": feature_errors[:8],
            }
        elif feature_files:
            result["feature_extraction"] = {"status": "ok"}
        artifacts.write_yaml("analysis", "07_analysis/ir_features.yaml", result)
    except (OSError, ValueError, PolicyError) as exc:
        result = {**result, "status": "failed", "reason": f"IR artifact unavailable: {exc}"}
    # Explicit require is the only mode that blocks the analysis/ISA outcome;
    # auto must preserve the original dynamic profiling and validation path.
    required_failure = mode == "require" and result.get("status") != "ok"
    return {
        "ir_result": result,
        "stage_jobs": "analysis",
        **outcome.stage_result(
            state, rung="ir", ok=not required_failure, reason=result.get("reason", ""),
            status=result.get("status"), required=mode == "require",
            history=f"LLVM IR evidence: {result.get('status')} ({result.get('reason', '')}).",
        ),
    }
